/* eslint-disable no-restricted-syntax, no-invalid-this, no-underscore-dangle */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherit = require( '@stdlib/utils/inherit' );
var log = require( './../log.js' );
var config = require( './../config.js' );


// MAIN //

/**
* Server sent events manager.
*
* @private
* @constructor
* @param {Object} state - state object
* @returns {SSE} SSE instance
*/
function SSE( state ) {
	if ( !( this instanceof SSE ) ) {
		return new SSE( state );
	}
	EventEmitter.call( this );
	this._state = state;
	this._source = null;
	this._ack = null;
	this._lastID = -1;
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( SSE, EventEmitter );

/**
* Sends an acknowledgment to the server regarding the last received event.
*
* @name ack
* @memberof SSE.prototype
* @type {Function}
*/
setReadOnly( SSE.prototype, 'ack', function ack() {
	var opts = {
		'method': 'POST',
		'body': this._lastID.toString(),
		'credentials': 'same-origin'
	};
	log( 'Sending acknowledgement to server...' );
	fetch( config.routes.ack, opts )
		.then( onResponse )
		.catch( onError );

	/**
	* Callback invoked upon receiving an HTTP response.
	*
	* @private
	* @param {Response} response - response object
	* @returns {void}
	*/
	function onResponse( response ) {
		if ( response.ok ) {
			log( 'Successfully sent acknowledgment.' );
			return;
		}
		console.error( 'Encountered an error when sending acknowledgment. Status: %d.', response.status );
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	*/
	function onError( error ) {
		console.error( 'Encountered an error when sending acknowledgment. Error: %s.', error.message );
	}
});

/**
* Establishes a server connection for listening to events.
*
* @name connect
* @memberof SSE.prototype
* @type {Function}
* @param {Callback} [clbk] - callback to invoke upon completion
*/
setReadOnly( SSE.prototype, 'connect', function connect( clbk ) {
	var self;
	var src;

	self = this;

	src = new EventSource( config.routes.sse, {
		'withCredentials': true
	});
	src.addEventListener( 'error', onError );
	src.addEventListener( 'open', onOpen );
	src.addEventListener( 'ping', onPing );

	src.addEventListener( 'data', onData );
	src.addEventListener( 'patch', onPatch );
	src.addEventListener( 'refresh', onRefresh );

	this._source = src;

	/**
	* Callback invoked when unable to establish a server connection.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onError() {
		var err = new Error( 'Failed to establish server connection.' );
		if ( self._ack ) {
			clearInterval( self._ack );
		}
		if ( clbk ) {
			return clbk( err );
		}
	}

	/**
	* Callback invoked upon establishing a server connection.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onOpen() {
		log( 'Established server connection.' );
		self._ack = setInterval( ack, config.ack.interval );
		if ( clbk ) {
			return clbk();
		}
	}

	/**
	* Sends an acknowledge to the server regarding the last received event.
	*
	* @private
	*/
	function ack() {
		self.ack();
	}

	/**
	* Callback invoked upon receiving a "ping" (keep-alive) message.
	*
	* @private
	*/
	function onPing() {
		log( 'Received a "ping" event.' );
	}

	/**
	* Callback invoked upon a "refresh" event.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onRefresh( event ) {
		log( 'Received a "refresh" event.' );
		self._lastID = event.id;
		self.emit( 'refresh', event );
	}

	/**
	* Callback invoked upon a "patch" event.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onPatch( event ) {
		log( 'Received a "patch" event.' );
		self._lastID = event.id;
		self.emit( 'patch', event );
	}

	/**
	* Callback invoked upon a "data" event.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onData( event ) {
		log( 'Received a "data" event.' );
		self._lastID = event.id;
		self.emit( 'data', event );
	}
});


// EXPORTS //

module.exports = SSE;
